const configured = (value) => Boolean(value) && !String(value).includes('__PENDIENTE__');

const parseAssignees = (raw, area) => {
  let mapping;
  try {
    mapping = JSON.parse(String(raw || ''));
  } catch (_error) {
    return { error: 'HANDOFF_CLICKUP_ASSIGNEES_JSON_invalid_json', assignees: [] };
  }
  const selected = mapping && typeof mapping === 'object' ? mapping[area] : null;
  const values = Array.isArray(selected) ? selected : [selected];
  const assignees = values
    .map((value) => Number(value))
    .filter((value) => Number.isSafeInteger(value) && value > 0);
  return assignees.length
    ? { error: null, assignees: [...new Set(assignees)] }
    : { error: `HANDOFF_CLICKUP_ASSIGNEES_JSON_missing_area:${area}`, assignees: [] };
};

const prepareHandoffClickup = (row, env = {}) => {
  const area = String(row.area || '').trim();
  const configErrors = [];
  if (!configured(env.CLICKUP_API_TOKEN)) configErrors.push('CLICKUP_API_TOKEN_missing');
  if (!configured(env.CLICKUP_LIST_ID)) configErrors.push('CLICKUP_LIST_ID_missing');
  const assignment = parseAssignees(env.HANDOFF_CLICKUP_ASSIGNEES_JSON, area);
  if (assignment.error) configErrors.push(assignment.error);

  const handoffId = Number(row.handoff_id);
  if (!Number.isSafeInteger(handoffId) || handoffId <= 0) configErrors.push('handoff_id_invalid');

  const description = [
    `Handoff interno #${handoffId || 'unknown'}`,
    `Área: ${row.area_label || area || 'No informada'}`,
    `Responsable: ${row.responsable || 'No informado'}`,
    `Prioridad: ${row.prioridad || 'No informada'}`,
    `Motivo: ${row.motivo || 'No informado'}`,
    `Cliente: ${row.phone_number || 'No informado'}`,
    `Conversación: ${row.conversation_id || 'No informada'}`,
    row.escalation_reason ? `Detalle: ${row.escalation_reason}` : null,
    `Idempotency key: ${row.idempotency_key || row.operation_key || ''}`,
  ].filter(Boolean).join('\n');

  return {
    ...row,
    clickup_config_error: configErrors.length ? configErrors.join(',') : null,
    should_dispatch_clickup: configErrors.length === 0,
    clickup_url: configErrors.length ? null : `https://api.clickup.com/api/v2/list/${encodeURIComponent(env.CLICKUP_LIST_ID)}/task`,
    clickup_payload: configErrors.length ? null : {
      name: `[HANDOFF #${handoffId}] ${row.area_label || area} - ${row.motivo || 'escalamiento'}`,
      description,
      assignees: assignment.assignees,
      priority: row.prioridad === 'urgente' ? 1 : row.prioridad === 'alta' ? 2 : 3,
    },
  };
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { configured, parseAssignees, prepareHandoffClickup };
}

if (typeof items !== 'undefined') {
  return [{ json: prepareHandoffClickup(items[0]?.json ?? {}, $env ?? {}) }];
}

const normalizedBody = (value) => {
  if (typeof value !== 'string') return value || {};
  try { return JSON.parse(value); } catch (_error) { return { raw: value }; }
};

const result = (row, outcome, statusCode, body, options = {}) => ({
  ...row,
  notification_outcome: outcome,
  notification_status_code: statusCode,
  notification_external_id: options.externalId || null,
  notification_external_url: options.externalUrl || null,
  notification_error: options.error || null,
  notification_retry_safe: Boolean(options.retrySafe),
  notification_response_json: JSON.stringify(normalizedBody(body)),
});

const dispatchHandoffClickup = async (row, httpRequest, apiToken) => {
  if (!row.should_dispatch_clickup) {
    return result(row, 'deferred', 0, {}, {
      error: row.clickup_config_error || 'clickup_configuration_missing',
      retrySafe: false,
    });
  }

  try {
    const response = await httpRequest({
      method: 'POST',
      url: row.clickup_url,
      headers: { Authorization: apiToken, 'Content-Type': 'application/json' },
      body: row.clickup_payload,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 30000,
    });
    const statusCode = Number(response?.statusCode || 0);
    const body = normalizedBody(response?.body);
    if (statusCode >= 200 && statusCode < 300) {
      if (!body.id) {
        return result(row, 'unknown', statusCode, body, {
          error: 'clickup_success_missing_task_id',
          retrySafe: false,
        });
      }
      return result(row, 'succeeded', statusCode, body, {
        externalId: body.id ? String(body.id) : null,
        externalUrl: body.url ? String(body.url) : null,
      });
    }
    if (statusCode === 425 || statusCode === 429) {
      return result(row, 'failed', statusCode, body, {
        error: `clickup_retryable_http_${statusCode}`,
        retrySafe: true,
      });
    }
    if (statusCode === 0 || statusCode === 408 || statusCode >= 500) {
      return result(row, 'unknown', statusCode, body, {
        error: `clickup_ambiguous_http_${statusCode}`,
        retrySafe: false,
      });
    }
    return result(row, 'failed', statusCode, body, {
      error: `clickup_http_${statusCode}`,
      retrySafe: false,
    });
  } catch (error) {
    return result(row, 'unknown', 0, {}, {
      error: String(error?.message || 'clickup_transport_error'),
      retrySafe: false,
    });
  }
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { normalizedBody, dispatchHandoffClickup };
}

if (typeof items !== 'undefined') {
  return dispatchHandoffClickup(items[0]?.json ?? {}, helpers.httpRequest.bind(helpers), $env.CLICKUP_API_TOKEN)
    .then((output) => [{ json: output }]);
}
